#[test]
fn jacobian_conjecture_session_using_dollar_delimiters_renders_mathbb_c_3_to_mathbb() {
    check(&[
        ("\\mathbb{C}^3 \\to \\mathbb{C}^3", false, Some("ℂ³ → ℂ³")),
    ]);
}

