fn treats_a_backslash_followed_by_a_line_ending_as_control_space() {
    check(&[
        ("\\boxed{\n(1,1,1),\\ (1,1,2),\\ (1,2,5),\\ (1,5,13),\\ (2,5,29),\\\n(1,13,34),\\ (1,34,89)\n}.", true, Some("[(1,1,1), (1,1,2), (1,2,5), (1,5,13), (2,5,29), (1,13,34), (1,34,89)].")),
        ("a\\\r\nb", false, Some("a b")),
    ]);
}

/// renderLatex / stacks operator limits in display mode
#[test]
fn stacks_operator_limits_in_display_mode() {
    check(&[
        ("\\sum_{i=0}^n x_i", true, Some(" n\n ∑  xᵢ\ni=0")),
        ("\\min_{x\\in X} f(x)", true, Some("min f(x)\nx∈X")),
        ("\\operatorname*{arg\\,max}_{x\\in X} f(x)", true, Some("arg max f(x)\n  x∈X")),
        ("\\int\\nolimits_0^1 f(x)\\,dx", true, Some("∫₀¹ f(x) dx")),
        ("\\int\\limits_0^1 f(x)\\,dx", true, Some("1\n∫ f(x) dx\n0")),
    ]);
}

/// renderLatex / centers even case rows around a middle brace
#[test]
fn centers_even_case_rows_around_a_middle_brace() {
    check(&[
        ("f(x) = \\begin{cases} x^{2} & x \\geq 0 \\\\ -x & x < 0 \\end{cases}", false, Some("       ⎧ x² if x ≥ 0\nf(x) = ⎨\n       ⎩ -x if x < 0")),
    ]);
}

/// renderLatex / stacks fractions in display mode
#[test]
fn stacks_fractions_in_display_mode() {
    check(&[
        ("x=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}", true, Some("    -b±√(b²-4ac)\nx = ────────────\n         2a")),
        ("\\frac{x^2+1}{x-1}", true, Some("x²+1\n────\nx-1")),
        ("\\frac{1}\n{2}", true, Some("1\n─\n2")),
    ]);
}

/// renderLatex / keeps nested display fractions linear
#[test]
fn keeps_nested_display_fractions_linear() {
    check(&[
        ("\\frac{\\frac{x^2+1}{x-1}-\\frac{2x}{x+1}}{\\frac{x}{x^2-1}}", true, Some("(x²+1)/(x-1)-2x/(x+1)\n─────────────────────\n      x/(x²-1)")),
        ("\\lim_{x\\to 0}\\frac{\\frac{\\sin x}{x}-1}{\\frac{e^x-1}{x}-1}=0", true, Some("     (sin x)/x-1\nlim  ─────────── = 0\nx→0  (eˣ-1)/x-1")),
        ("\\frac{1+\\frac{1}{1+\\frac{1}{x}}}{1-\\frac{1}{1-\\frac{1}{x}}}", true, Some("1+1/(1+1/x)\n───────────\n1-1/(1-1/x)")),
    ]);
}

/// renderLatex / lays out unsupported and nested scripts while keeping script fractions linear
#[test]
fn lays_out_unsupported_and_nested_scripts_while_keeping_script_fractions_linear() {
    check(&[
        ("\\partial_tU_2(t,0)=Aj_*(1-t)^{-A-1}.\\qquad x^{n^2}+x_{i_j}", true, Some("                            2\n                    -A-1   n\n∂ₜU₂(t,0) = Aj (1-t)    . x  +x\n              *                i\n                                j")),
        ("e^{\\frac{1}{2}}+\\tfrac{1}{2}", true, Some("e^(1/2)+1/2")),
    ]);
}

/// renderLatex / returns undefined for unsupported commands
#[test]
fn returns_undefined_for_unsupported_commands() {
    check(&[
        ("x + \\unknown{y}", false, None),
    ]);
}

/// renderLatex / returns undefined for malformed groups and environments
#[test]
fn returns_undefined_for_malformed_groups_and_environments() {
    check(&[
        ("\\frac{1}{x", false, None),
        ("x}", false, None),
        ("\\begin{matrix}1 & 2", false, None),
        ("x\\", false, None),
    ]);
}
